"""Week1 = Baselines, explicitly identified by the user. No legacy narrative evidence."""
from reportlib import *
import re,math,numpy as np,yaml

def main():
 out=BASE/'week_01';out.mkdir(exist_ok=True);root='Baselines/SARA-main/';nb=root+'notebooks/sara_baseline_checkpoints.ipynb';n=obj(nb)
 def text(index):return '\n'.join(''.join(o.get('text',[])) or ''.join(o.get('data',{}).get('text/plain',[])) for o in n['cells'][index].get('outputs',[]))
 manifest=root+'data/manifests/qasper_split.json';m=obj(manifest);splitrows=[]
 for label,key in [('TRAIN','train_split'),('DEV','dev')]:
  path=root+'data/reformatted/QASPER_'+key+'.jsonl';data=[json.loads(l) for l in (ROOT/path).open() if l.strip()];papers={str(x['example_id']) for x in data};assert len(data)==m['n_rows_'+label.lower()];assert len(papers)==m['n_papers_'+label.lower()]
  splitrows.append(dict(split=label,queries=len(data),papers=len(papers),source=path))
 assert not set(m['train_paper_ids'])&set(m['dev_paper_ids'])
