 (out/'SplitRecomputation.json').write_text(json.dumps(dict(week_mapping='User explicitly maps Baselines/ to Week1',split_rows=splitrows,train_dev_paper_overlap=0,test_questions_or_outcomes_read=False),indent=2)+'\n')
 training=[];logs=[];args=[];cps=[]
 for method,name in [('RAG','rag_qasper_lora_r16_seed42'),('SARA','sara_qasper_proj_lr5e4_seed42')]:
  p=root+'checkpoints/finetune/'+name+'/';cps.append(p);a=obj(p+'args.json');t=obj(p+'checkpoint-250/trainer_state.json');args.append(a);history=t['log_history'];assert t['global_step']==250;assert all(math.isfinite(float(x['loss'])) for x in history if 'loss' in x)
  for x in history:
   if 'loss' in x:logs.append(dict(method=method,step=x['step'],loss=x['loss'],grad_norm=x.get('grad_norm'),epoch=x.get('epoch'),learning_rate=x.get('learning_rate')))
  trainsteps=[x['step'] for x in history if 'loss' in x];assert len(trainsteps)==250 and trainsteps==list(range(1,251))
  training.append(dict(method=method,global_step=t['global_step'],logged_steps=len(trainsteps),recorded_epoch=t['epoch'],saved_num_train_epochs=a['num_train_epochs'],saved_num_evidence=a['num_evidence'],saved_num_additional_evidence=a['num_additional_evidence'],model_learning_rate=a['model_learning_rate'],projector_learning_rate=a['projector_learning_rate'],batch_size=a['per_device_train_batch_size'],gradient_accumulation=a['gradient_accumulation_steps'],max_train_samples_argument=a['max_train_samples'],mean_logged_training_loss=np.mean([x['loss'] for x in history if 'loss' in x]),last_logged_training_loss=history[-1]['loss'],max_logged_grad_norm=max(float(x['grad_norm']) for x in history if x.get('grad_norm') is not None),best_metric=t.get('best_metric'),adapter_weight_bytes=(ROOT/p/'adapter_model.safetensors').stat().st_size))
 T=pd.DataFrame(training);L=pd.DataFrame(logs);T.to_csv(out/'TrainingRecomputation.csv',index=False);L.to_csv(out/'TrainingLogExtract.csv',index=False)
 ragconfig=root+'config/language_modeling/Finetune_RAG_qasper_pubbase.yaml';saraconfig=root+'config/language_modeling/Finetune_SARA_qasper_pubbase.yaml'
 epochs=[]
 for i,path in enumerate([ragconfig,saraconfig]):
  c=yaml.safe_load((ROOT/path).read_text());epochs.append(dict(method=training[i]['method'],current_yaml_epochs=c['num_train_epochs'],saved_run_epochs=args[i]['num_train_epochs'],source=path))
 assert 'Num examples = 506' in text(10);assert 'train_runtime' in text(10);assert 'torch.OutOfMemoryError' in text(11)
 match=re.search(r"'train_runtime':\s*([\d.]+).*?'train_loss':\s*([\d.]+)",text(10));assert match
 runtime=float(match.group(1));ragloss=float(match.group(2));profile=text(13);assert n['cells'][13].get('execution_count') is not None
 profiles=[]
