 reco='Baselines/recomp-main/data/completions/flan_ul2_nq_5shot_no_passage.csv';r=frame(reco)
 base=dict(week_scope='Baselines/ as explicitly mapped by the user',dataset='Local SARA QASPER TRAIN2088 / DEV231; checkpoint training coverage differs',base_model='mistralai/Mistral-7B-Instruct-v0.2',tokenizer='Mistral tokenizer plus saved special tokens',seed=42,optimizer_updates=250,trainable_components='RAG LM-LoRA; SARA LM-LoRA + retrieval projector')
 parts=[part('A','Dataset construction and paper-disjoint split','Which local examples underpin the reproduced SARA/RAG baselines?',paths=[manifest,root+'data/reformatted/QASPER_train_split.jsonl',root+'data/reformatted/QASPER_dev.jsonl'],tables=[(manifest,pd.DataFrame(splitrows),'Manifest counts independently checked against TRAIN/DEV JSONL')],design=base,finding='The manifest and raw files agree:2088 TRAIN queries/772 papers,231 DEV queries/86 papers, and zero TRAIN/DEV paper overlap. TEST has1309 rows according to metadata only; its questions/outcomes were not loaded for this reconstruction.',caveat='These are local SARA splits, not a claim about official dataset split sizes or a current untouched TEST. Training eligibility/actual coverage is a separate issue.'),part('B','Standard RAG checkpoint training','Was a projector-free RAG adapter actually trained rather than merely configured?',paths=[cps[0]+'args.json',cps[0]+'checkpoint-250/trainer_state.json',ragconfig,nb],tables=[(cps[0]+'checkpoint-250/trainer_state.json',T[T.method=='RAG'],'Saved RAG training record'),(nb,pd.DataFrame([dict(notebook_cell=10,num_examples_logged=506,reported_training_runtime_seconds=runtime,reported_training_loss=ragloss)]),'Executed RAG notebook training log')],design=base|{'text_evidence':10,'compressed_evidence':0},finding='RAG has250 logged optimizer steps and a saved adapter. Executed notebook cell10 reports506 training examples, runtime14988.353 seconds and train_loss5.325839; the final logged step loss2.9502 is a different quantity.',caveat='SOURCE CONFLICT: current YAML says3 epochs, saved run args say2. The local split has2088 rows and max_train_samples argument2000, but the executed log records506 training examples. Do not claim full-split exposure or infer unique examples actually consumed without a sampler trace. Training loss is not answer F1.'),part('C','SARA checkpoint training','Was the text-plus-latent baseline trained, and how does its execution provenance differ from RAG?',paths=[cps[1]+'args.json',cps[1]+'checkpoint-250/trainer_state.json',cps[1]+'sara_config.json',saraconfig,nb],tables=[(cps[1]+'checkpoint-250/trainer_state.json',T[T.method=='SARA'],'Saved SARA training record'),(saraconfig,pd.DataFrame(epochs),'Current configuration versus saved-run epoch identity')],design=base|{'text_evidence':5,'compressed_evidence':5,'compressor':'Salesforce/SFR-Embedding-Mistral; saved retriever_hidden_size4096'},finding='The SARA checkpoint trainer state records250 optimizer steps and epoch0.501002, with last logged loss5.4034. Saved args use one epoch, unlike current YAML3. Notebook cell11 preserves an OOM-failed training attempt; that specific failure and the separately saved completed checkpoint must both be retained.',caveat='The exact chronology/resume path linking the failed notebook attempt to the saved checkpoint is not established. Equal optimizer-step counts do not establish equal training-example coverage, training tasks or model quality. Projector/adaptation changes make later RAG/SARA comparisons whole-system comparisons.'),part('D','Checkpoint loading / interface qualification','Can both saved checkpoints load with their intended projector/tokenizer interfaces?',paths=[nb,cps[0]+'adapter_config.json',cps[1]+'adapter_config.json',cps[1]+'sara_config.json'],tables=[(nb,P,'Executed notebook cell13 checkpoint profiles')],design=base,status='SMOKE-TESTED',finding='Executed cell13 records RAG/SARA loading in10.23/9.67 seconds, peak GPU13.51/13.58 GiB, compress token32001 and vocabulary32002. RAG is projector-free; SARA prints nonzero projector norm164.',caveat='A nonzero projector norm establishes neither semantic quality nor successful training by itself. These are loading diagnostics on the recorded machine, not end-to-end inference throughput. Cell15 has generation text but no execution_count; its generation claim is not accepted as a reliably executed outcome.'),part('E','Training-curve diagnostics','What do the saved loss trajectories establish about baseline training?',paths=[cps[0]+'checkpoint-250/trainer_state.json',cps[1]+'checkpoint-250/trainer_state.json'],tables=[('results/weekly_reports/week_01/TrainingRecomputation.csv',T[['method','logged_steps','recorded_epoch','mean_logged_training_loss','last_logged_training_loss','max_logged_grad_norm']],'Offline recomputed log summaries')],design=base,finding='Both trainer histories contain250 finite logged losses. Their means/final losses are recomputed in the table; differences cannot be interpreted as comparative QA accuracy.',caveat='Losses reflect different representation/training interfaces and potentially different eligible samples. Logged grad_norm may be measured before clipping; large norms alone do not prove clipping failed.',figures=[('results/weekly_reports/week_01/figures/logged_training_loss.png','X-axis is optimizer step; y-axis is saved logged training loss. This new offline figure is derived only from original trainer states. It shows training dynamics, not answer-quality superiority or matched-example convergence.')]),part('F','QA evaluation scaffold','Is there a standalone completed Week1 answer-quality comparison in Baselines?',paths=[root+'src/eval/eval_sara.py',root+'src/eval/calculate_qa_performance.py',root+'src/run_sara.py'],status='IMPLEMENTED',design=base,finding='Evaluation code exists, but no standalone completed local Week1 QA score table or raw evaluation result was located inside Baselines. Week2 outcomes are not copied backward into Week1.',caveat='A loadable/trained checkpoint and commented evaluation commands are not completed quality evaluation.',decision='The later Week2 fixed-k matrix supplies explicit downstream performance for the saved baseline families.'),part('G','SANE baseline source','Which additional evidence-selection/extraction baseline is implemented?',paths=['Baselines/SANE-main/config/default.yaml','Baselines/SANE-main/benchmarks/metrics.py','Baselines/SANE-main/sane/agents/sane_agent.py'],status='IMPLEMENTED',design={'scope':'Vendored/current SANE implementation; no Week1 execution snapshot established'},finding='SANE code/configuration and benchmark interfaces are present. No completed local Week1 SANE quality run was found; current default model/config must not be assumed to be its historical Week1 frozen identity.',caveat='Do not confuse Week9 SANE-adapted diagnostic outcomes with a faithful independently reproduced original SANE benchmark.'),part('H','RECOMP baseline source and bundled completions','Does the RECOMP checkout establish a locally executed baseline comparison?',paths=['Baselines/recomp-main/run_extractive_compressor.py','Baselines/recomp-main/train_extractive_compressor.py','Baselines/recomp-main/eval_qa.py',reco],tables=[(reco,pd.DataFrame([dict(rows=len(r),question_rows=int(r.question.notna().sum()),prediction_rows=int(r.pred_answer.notna().sum()),columns=','.join(r.columns))]),'Bundled completion-file inventory; not a locally verified run')],status='IMPLEMENTED',design={'scope':'RECOMP source and shipped FLAN-UL2 Natural Questions completion file'},finding='RECOMP implementation is present with a3610-row bundled NQ completion CSV. Its local generation provenance is not established, so it is not counted as a completed Week1 experiment or a QASPER result.',caveat='Different dataset/model, no local execution receipt. Published/paper figures in Baselines/papers or media are reference material, not primary local experimental evidence.')]
 context=[nb,ragconfig,saraconfig,root+'src/train/train_generator.py',root+'scripts/build_qasper_dataset.py',root+'src/data/make_qasper_splits.py','results/weekly_reports/week_01/SplitRecomputation.json','results/weekly_reports/week_01/TrainingRecomputation.csv','results/weekly_reports/week_01/TrainingLogExtract.csv','results/weekly_reports/week_01/CheckpointProfilingExtract.csv','results/weekly_reports/week_01/NotebookExecutionChecks.json']
 write_week(1,'Reconstruct the baseline implementation, local split, actual SARA/RAG training and checkpoint qualification under Baselines/. User-provided scope resolves the previous missing Week1 mapping; code availability is separated from trained checkpoints and answer-quality evaluation.',parts,context,checks=['User explicitly identifies Baselines/ as Week1; previous no-tagged-directory gap is superseded, not hidden.','TRAIN/DEV counts and paper disjointness verified from raw files and split manifest.','Both trainer states have global_step250 and exactly250 consecutive loss records.','Notebook cell10 logs506 RAG examples; current/saved epoch settings differ; SARA failed attempt and completed checkpoint are distinct records.','No TEST questions/outcomes, unsafe pickle weights or model runs were needed.'],transition='Week2 provides a frozen231-query fixed-k quality response surface using these baseline checkpoint families; Week1 does not borrow its numerical results.',decision='Saved public-base RAG and SARA checkpoints exist for later controlled evaluation. SANE/RECOMP are implemented references with no verified local Week1 performance.',negative='SARA notebook training attempt OOMs; no completed standalone Week1 QA quality comparison or local SANE/RECOMP benchmark is established.',limits='Baseline training sample/epoch identities are not fully matched; quality is not established by training losses, load timing, projector norm or bundled external completions.',revision_reason='User explicitly clarified that Baselines/ is Week1; replace the prior discovery-only gap with primary-artifact evidence.')
